def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple implementation to find first differing substring
    if s_in == s_out:
        return None

    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached the end of one string
    if pos >= len(s_in) or pos >= len(s_out):
        # Check if one is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[pos:], s_out[pos:], pos)
        else:
            return (s_in[pos:], s_out[pos:], pos)

    # Find the longest substring that needs to be replaced
    # We'll start with single character replacement for simplicity
    if len(s_in) == len(s_out):
        # Same length - check if it's a simple substitution
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
    elif len(s_in) > len(s_out):
        # Deletion case
        return (s_in[pos], s_out[pos], pos)
    else:
        # Insertion case
        return (s_in[pos], s_out[pos], pos)

